CREATE TABLE "ocorrencia" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "ocorrencia_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"protocolo" varchar(16) NOT NULL,
	"ano" integer NOT NULL,
	"numero" integer NOT NULL,
	"situacao" varchar(20) DEFAULT 'REGISTRADA' NOT NULL,
	"data_hora" timestamp with time zone NOT NULL,
	"campus_id" integer NOT NULL,
	"local_descricao" varchar(200) NOT NULL,
	"tipos" varchar(300) NOT NULL,
	"tipo_outro" varchar(120),
	"descricao" text NOT NULL,
	"observacoes" text,
	"durante_atividade" varchar(8),
	"pessoa_nome" varchar(160),
	"pessoa_vinculo" varchar(12) NOT NULL,
	"pessoa_vinculo_outro" varchar(80),
	"nivel_ensino" varchar(14),
	"curso" varchar(120),
	"setor_lotacao" varchar(120),
	"acidente_em_servico" varchar(8),
	"empresa" varchar(120),
	"funcao" varchar(120),
	"registrado_por" integer NOT NULL,
	"notificante_eh_a_pessoa" boolean NOT NULL,
	"notificante_nome" varchar(160) NOT NULL,
	"notificante_telefone" varchar(30),
	"notificante_email" varchar(254),
	"encaminhada_pronto_atendimento" boolean DEFAULT false NOT NULL,
	"meio_deslocamento" varchar(20),
	"meio_deslocamento_outro" varchar(80),
	"assumida_por" integer,
	"assumida_em" timestamp with time zone,
	"concluida_em" timestamp with time zone,
	"conclusao" text,
	"acidente_id" integer,
	"criado_em" timestamp with time zone NOT NULL,
	"atualizado_em" timestamp with time zone,
	CONSTRAINT "ck_ocorrencia_protocolo" CHECK (protocolo ~ '^(?:^OCO-[0-9]{4}-[0-9]{4,}$)$'),
	CONSTRAINT "ck_ocorrencia_situacao" CHECK (situacao IN ('REGISTRADA','EM_ACOMPANHAMENTO','CONCLUIDA','CANCELADA')),
	CONSTRAINT "ck_ocorrencia_vinculo" CHECK (pessoa_vinculo IN ('ESTUDANTE','SERVIDOR','TERCEIRIZADO','OUTRO')),
	CONSTRAINT "ck_ocorrencia_nivel_ensino" CHECK (nivel_ensino IS NULL OR nivel_ensino IN ('GRADUACAO','POS_GRADUACAO','NAO_SEI')),
	CONSTRAINT "ck_ocorrencia_durante_atividade" CHECK (durante_atividade IS NULL OR durante_atividade IN ('SIM','NAO','NAO_SEI')),
	CONSTRAINT "ck_ocorrencia_em_servico" CHECK (acidente_em_servico IS NULL OR acidente_em_servico IN ('SIM','NAO','NAO_SEI')),
	CONSTRAINT "ck_ocorrencia_meio" CHECK (meio_deslocamento IS NULL OR meio_deslocamento IN ('BOMBEIROS','SAMU','VEICULO_UFVJM','VEICULO_PARTICULAR','OUTRO')),
	CONSTRAINT "ck_ocorrencia_meio_exige_encaminhamento" CHECK (meio_deslocamento IS NULL OR encaminhada_pronto_atendimento)
);
